head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf05500";
scwin.dmenus = undefined;
scwin.cntr_cd = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":2
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05500' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.cntr_cd = '' + dma_companyInfoVO.get("cntrIsoCd") + '';
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf05500.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_usrNm_onblur
 * @description ipt_usrNm 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_usrNm_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.chk_chrg_nm(selfVar, 20, '담당자 이름');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_usrNm_onblur' }); }
};

/**
 * @method
 * @name ipt_usrNm_onkeypress
 * @description ipt_usrNm onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_usrNm_onkeypress = function(e){
    try {
        fn_etcNumNotCheck()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_etcNumNotCheck — 키 입력 필터(window.event — xf:input allowChar 속성 권장)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_usrNm_onkeypress' }); }
};

/**
 * @method
 * @name ipt_telNo_onkeydown
 * @description ipt_telNo 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_telNo_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        fn_telNoCheck(selfVar);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_telNoCheck — 키 입력 필터(window.event — xf:input allowChar 속성 권장)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_telNo_onkeydown' }); }
};

/**
 * @method
 * @name ipt_telNo_onblur
 * @description ipt_telNo 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_telNo_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        Chk_Phone(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_telNo_onblur' }); }
};

/**
 * @method
 * @name ipt_cellphoneNo_onkeydown
 * @description ipt_cellphoneNo 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
