 * @method
 * @name ipt_cellphoneNo_onblur
 * @description ipt_cellphoneNo 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_cellphoneNo_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        Chk_Phone(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_cellphoneNo_onblur' }); }
};

/**
 * @method
 * @name ipt_faxNo_onkeydown
 * @description ipt_faxNo 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_faxNo_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        fn_telNoCheck(selfVar);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_telNoCheck — 키 입력 필터(window.event — xf:input allowChar 속성 권장)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_faxNo_onkeydown' }); }
};

/**
 * @method
 * @name ipt_faxNo_onblur
 * @description ipt_faxNo 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
