 */
scwin.ipt_faxNo_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        Chk_Fax(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_faxNo_onblur' }); }
};

/**
 * @method
 * @name ipt_encrypChrgEmail1_onkeydown
 * @description ipt_encrypChrgEmail1 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypChrgEmail1_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_encrypChrgEmail1_onkeydown' }); }
};

/**
 * @method
 * @name ipt_encrypChrgEmail2_onkeydown
 * @description ipt_encrypChrgEmail2 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_encrypChrgEmail2_onkeydown = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.emailCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05500.ipt_encrypChrgEmail2_onkeydown' }); }
};

/**
 * @method
 * @name btn_fnSubmit_onclick
 * @description btn_fnSubmit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSubmit_onclick = async function(e){
    try {
        await scwin.fnSubmit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05500.btn_fnSubmit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSubmit
 * @description fn Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSubmit",
        method: "post",
        action: "/account/userInfo.do",
        ref: "dma_fnSubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name fnSubmit
 * @description fn Submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSubmit = async function () {
    const fm = (document.SendForm || { elements: [] });
    if (!await scwin.ReqDataCheckValues(fm)) {
        return;
    }
    if ($c.util.getComponent('dma_fnSubmitReq').get('cntrIsoCd')=== '410') {
        $c.util.getComponent("ipt_telNo").setValue($c.util.getComponent('ipt_chrgTelNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo3').getValue());
        $c.util.getComponent("ipt_cellphoneNo").setValue($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue());
        $c.util.getComponent("ipt_faxNo").setValue($c.util.getComponent('ipt_chrgFaxNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo3').getValue());
        $c.util.getComponent("ipt_innrNo").setValue($c.util.getComponent('ipt_chrgInnrNo1').getValue());
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue().trim()) > 0 && $c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue().trim()) > 0) {
        $c.util.getComponent('dma_fnSubmitReq').set('email', $c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ "@" + $c.util.getComponent('ipt_encrypChrgEmail2').getValue());
    }
    if (await $c.win.confirm("변경하시겠습니까?")) {
        $c.util.getComponent('dma_fnSubmitReq').set('method', "modifyUserInfo");
        await scwin.tx_fnSubmit();
    }
};

/**
 * @method
 * @name fnReset
 * @description fn Reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnReset = function () {
    (document.SendForm || { elements: [] }).reset();
};

/**
 * @method
 * @name ReqDataCheckValues
 * @description Req Data Check Values 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ReqDataCheckValues = async function (fm) {
    if ($c.str.getByteLength($c.util.getComponent('ipt_usrNm').getValue()) === 0) {
        await $c.win.alert("발행기관의 담당자이름을 입력해주십시오.");
        $c.util.getComponent("ipt_usrNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_belngDepNm').getValue()) === 0) {
        await $c.win.alert("발행기관의 담당자소속부서를 입력해주십시오.");
        $c.util.getComponent("ipt_belngDepNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_jobtitlNm').getValue()) === 0) {
        await $c.win.alert("발행기관의 담당자직책을 입력해주십시오.");
        $c.util.getComponent("ipt_jobtitlNm").focus();
        return false;
    }
    if ($c.util.getComponent('dma_fnSubmitReq').get('cntrIsoCd')=== '410') {
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo1').getValue()) === 0) {
            await $c.win.alert("발행기관의 담당자전화번호를 입력해주십시오.");
            $c.util.getComponent("ipt_chrgTelNo1").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo2').getValue()) === 0) {
                await $c.win.alert("발행기관의 담당자전화번호를 입력해주십시오.");
                $c.util.getComponent("ipt_chrgTelNo2").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo3').getValue()) === 0) {
                    await $c.win.alert("발행기관의 담당자전화번호를 입력해주십시오.");
                    $c.util.getComponent("ipt_chrgTelNo3").focus();
                    return false;
                }
            }
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()) === 0) {
            await $c.win.alert("발행기관의 담당자휴대전화번호를 입력해주십시오.");
            $c.util.getComponent("ipt_encrypCellphoneNo1").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo2').getValue()) === 0) {
                await $c.win.alert("발행기관의 담당자휴대전화번호를 입력해주십시오.");
                $c.util.getComponent("ipt_encrypCellphoneNo2").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo3').getValue()) === 0) {
                    await $c.win.alert("발행기관의 담당자휴대전화번호를 입력해주십시오.");
                    $c.util.getComponent("ipt_encrypCellphoneNo3").focus();
                    return false;
                }
            }
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo1').getValue()) === 0) {
            await $c.win.alert("발행기관의 담당자팩스번호를 입력해주십시오.");
            $c.util.getComponent("ipt_chrgFaxNo1").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo2').getValue()) === 0) {
                await $c.win.alert("발행기관의 담당자팩스번호를 입력해주십시오.");
                $c.util.getComponent("ipt_chrgFaxNo2").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo3').getValue()) === 0) {
                    await $c.win.alert("발행기관의 담당자팩스번호를 입력해주십시오.");
                    $c.util.getComponent("ipt_chrgFaxNo3").focus();
                    return false;
                }
            }
        }
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_cellphoneNo').getValue()) === 0) {
            await $c.win.alert("담당자 휴대전화번호를 입력하세요.");
            $c.util.getComponent("ipt_cellphoneNo").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_telNo').getValue()) === 0) {
            await $c.win.alert("담당자 전화번호를 입력하세요.");
            $c.util.getComponent("ipt_telNo").focus();
            return false;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue()) === 0) {
        await $c.win.alert("발행기관의 담당자 이메일을 입력해주십시오.");
        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue()) === 0) {
            await $c.win.alert("발행기관의 담당자 이메일을 입력해주십시오.");
            $c.util.getComponent("ipt_encrypChrgEmail2").focus();
            return false;
        } else {
            const email = $c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypChrgEmail2').getValue();
            if (!$c.str.isEmail(email)) {
                await $c.win.alert("발행기관의 담당자 이메일이 올바르지 않습니다.");
                $c.util.getComponent("ipt_encrypChrgEmail2").focus();
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
};
